import {rareRenderers} from './rare-experiments.js';
import {extraRenderers} from './extended-experiments.js';
import {wave,waveAmplitude,secant,tangent,hypotenuse,branchCount} from './math.js';
const C={blue:'#93b9fa',mint:'#b4f2d5',amber:'#efbd81',pink:'#ef96ba',purple:'#c1a0f5',muted:'#8e9eb3',white:'#edf2f6',grid:'#203046'};
export class Experiment{
 constructor(canvas,onChange){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.onChange=onChange;this.t=0;this.paused=false;this.drag=false;this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(canvas);canvas.addEventListener('pointerdown',e=>{if(this.id==='vectors'||this.id==='derivatives'){this.drag=true;canvas.setPointerCapture(e.pointerId);this.manipulate(e)}});canvas.addEventListener('pointermove',e=>{if(this.drag)this.manipulate(e)});canvas.addEventListener('pointerup',()=>this.drag=false);canvas.addEventListener('pointercancel',()=>this.drag=false);canvas.addEventListener('keydown',e=>{if(this.id!=='vectors'&&this.id!=='derivatives')return;let v={...this.v};if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(this.id==='vectors'){if(e.key==='ArrowLeft')v.x=Math.max(-4,v.x-.1);if(e.key==='ArrowRight')v.x=Math.min(4,v.x+.1);if(e.key==='ArrowUp')v.y=Math.min(3,v.y+.1);if(e.key==='ArrowDown')v.y=Math.max(-3,v.y-.1)}else v.x=Math.max(-2,Math.min(2,v.x+(e.key==='ArrowRight'?.05:-.05)));this.onChange(v)});}
 resize(){this.lastRenderKey=null;const r=this.canvas.getBoundingClientRect();this.w=r.width;this.h=r.height;const d=Math.min(devicePixelRatio,2);this.canvas.width=Math.max(1,Math.round(r.width*d));this.canvas.height=Math.max(1,Math.round(r.height*d));this.ctx.setTransform(d,0,0,d,0,0);}
 set(id,v,samples){this.lastRenderKey=null;this.id=id;this.v=v;this.samples=samples;this.t=0;this.resize()}
 manipulate(e){if(!this.plot)return;const r=this.canvas.getBoundingClientRect(),p=this.plot;const x=p.xmin+(e.clientX-r.left-p.left)/p.width*(p.xmax-p.xmin),y=p.ymax-(e.clientY-r.top-p.top)/p.height*(p.ymax-p.ymin);if(this.id==='vectors')this.onChange({...this.v,x:Math.round(Math.max(-4,Math.min(4,x))*10)/10,y:Math.round(Math.max(-3,Math.min(3,y))*10)/10});else this.onChange({...this.v,x:Math.round(Math.max(-2,Math.min(2,x))*20)/20})}
 text(txt,x,y,color=C.muted,size=13,align='left'){const c=this.ctx;c.fillStyle=color;c.font=`${size}px ${size>21?'Georgia':'monospace'}`;c.textAlign=align;c.fillText(txt,x,y)}
 line(points,color,width=2,dash=[]){const c=this.ctx;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.strokeStyle=color;c.lineWidth=width;c.setLineDash(dash);c.stroke();c.setLineDash([])}
 dot(x,y,color,r=5){const c=this.ctx;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fillStyle=color;c.shadowColor=color;c.shadowBlur=15;c.fill();c.shadowBlur=0}
 poly(points,color,fill=.14){const c=this.ctx;c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.globalAlpha=fill;c.fillStyle=color;c.fill();c.globalAlpha=1;c.lineWidth=1.6;c.strokeStyle=color;c.stroke()}
 arrow(a,b,color,dash=[]){this.line([a,b],color,2.5,dash);const angle=Math.atan2(b[1]-a[1],b[0]-a[0]);this.poly([b,[b[0]-12*Math.cos(angle-.4),b[1]-12*Math.sin(angle-.4)],[b[0]-12*Math.cos(angle+.4),b[1]-12*Math.sin(angle+.4)]],color,1)}
 chart(xmin,xmax,ymin,ymax){const p=this.plot={xmin,xmax,ymin,ymax,left:40,top:35,width:Math.max(50,this.w-70),height:Math.max(40,this.h-105)};const xy=(x,y)=>[p.left+(x-xmin)/(xmax-xmin)*p.width,p.top+(ymax-y)/(ymax-ymin)*p.height];for(let x=Math.ceil(xmin);x<=xmax;x++){this.line([xy(x,ymin),xy(x,ymax)],C.grid,.6);if(x%2===0)this.text(String(x),xy(x,ymin)[0],p.top+p.height+19,C.muted,10,'center')}for(let y=Math.ceil(ymin);y<=ymax;y++){this.line([xy(xmin,y),xy(xmax,y)],C.grid,.6);if(y%2===0)this.text(String(y),p.left-12,xy(xmin,y)[1]+4,C.muted,10,'right')}if(ymin<=0&&ymax>=0)this.line([xy(xmin,0),xy(xmax,0)],'#6e8095',1);if(xmin<=0&&xmax>=0)this.line([xy(0,ymin),xy(0,ymax)],'#6e8095',1);this.text('x',p.left+p.width+10,xy(0,0)[1],C.muted,11);this.text('y',xy(0,0)[0],p.top-10,C.muted,11);return xy}
 render(dt){if(!this.id||this.w<1||this.h<1)return;const key=this.id+JSON.stringify(this.v)+this.w+':'+this.h+':'+(this.samples?.total||0);if(this.id!=='waves'&&key===this.lastRenderKey)return;this.lastRenderKey=key;if(!this.paused)this.t+=dt;const c=this.ctx;c.clearRect(0,0,this.w,this.h);c.lineCap='round';this[this.id]();}
 waves(){const p=this.v.phase*Math.PI/180,xy=this.chart(-Math.PI*2,Math.PI*2,-2.6,2.6);const n=320;const series=[[],[],[]];for(let i=0;i<=n;i++){const x=-Math.PI*2+i/n*Math.PI*4;series[0].push(xy(x,Math.sin(x-this.t*.45)));series[1].push(xy(x,Math.sin(x-this.t*.45+p)));series[2].push(xy(x,wave(x-this.t*.45,p)))}this.line(series[0],C.mint,1.4);this.line(series[1],C.amber,1.4);this.line(series[2],C.white,3);this.text(`Resulting amplitude  ${waveAmplitude(p).toFixed(2)}`,this.w/2,this.h-38,C.white,15,'center');}
 vectors(){const xy=this.chart(-5,7,-4,5),{x,y}=this.v;this.arrow(xy(0,0),xy(x,y),C.blue);this.arrow(xy(0,0),xy(2,1),C.amber);this.arrow(xy(x,y),xy(x+2,y+1),C.amber,[5,5]);this.arrow(xy(0,0),xy(x+2,y+1),C.mint);this.dot(...xy(x,y),C.blue,7);this.text('a',xy(x,y)[0]-14,xy(x,y)[1]-13,C.blue,16);this.text('a + b',xy(x+2,y+1)[0]+8,xy(x+2,y+1)[1]-10,C.mint,14);this.text(`(${x.toFixed(1)}, ${y.toFixed(1)}) + (2, 1) = (${(x+2).toFixed(1)}, ${(y+1).toFixed(1)})`,this.w/2,this.h-37,C.white,this.w<450?11:15,'center');}
 fractals(){const{depth,angle,ratio}=this.v;const segments=[];const branch=(x,y,l,ang,level)=>{const x2=x+Math.cos(ang)*l,y2=y+Math.sin(ang)*l;segments.push({x,y,x2,y2,level});if(level<depth){branch(x2,y2,l*ratio,ang-angle*Math.PI/180,level+1);branch(x2,y2,l*ratio,ang+angle*Math.PI/180,level+1)}};branch(0,0,1,-Math.PI/2,0);let xmin=0,xmax=0,ymin=0,ymax=0;segments.forEach(s=>{xmin=Math.min(xmin,s.x2);xmax=Math.max(xmax,s.x2);ymin=Math.min(ymin,s.y2);ymax=Math.max(ymax,s.y2)});const scale=Math.min((this.w-60)/Math.max(.1,xmax-xmin),(this.h-105)/Math.max(.1,ymax-ymin));const xy=(x,y)=>[this.w/2+(x-(xmin+xmax)/2)*scale,35+(y-ymin)*scale];segments.forEach(s=>{this.line([xy(s.x,s.y),xy(s.x2,s.y2)],s.level===0?C.purple:C.mint,Math.max(.7,(depth-s.level+1)*.55));if(s.level===depth&&depth<8)this.dot(...xy(s.x2,s.y2),C.purple,1.5)});this.text(`${branchCount(depth).toLocaleString()} branches · depth ${depth}`,this.w/2,this.h-36,C.white,15,'center');}
 derivatives(){const{x,h}=this.v,xy=this.chart(-3,4,-2,14);const c=this.ctx;c.save();c.beginPath();c.rect(this.plot.left,this.plot.top,this.plot.width,this.plot.height);c.clip();const pts=[];for(let a=-3;a<=4;a+=.025)pts.push(xy(a,a*a));this.line(pts,C.white,2.5);this.line([xy(-3,x*x+tangent(x)*(-3-x)),xy(4,x*x+tangent(x)*(4-x))],C.mint,2);this.line([xy(-3,x*x+secant(x,h)*(-3-x)),xy(4,x*x+secant(x,h)*(4-x))],C.amber,2,[6,4]);this.dot(...xy(x,x*x),C.blue,7);this.dot(...xy(x+h,(x+h)**2),C.amber,6);c.restore();this.text(`Secant ${secant(x,h).toFixed(2)}   →   tangent ${tangent(x).toFixed(2)}`,this.w/2,this.h-37,C.white,this.w<420?12:16,'center');}
 probability(){const s=this.samples||{values:[],hits:0,total:0},cols=Math.max(10,Math.floor((this.w-60)/13)),maxRows=Math.max(2,Math.floor((this.h-130)/13)),visible=s.values.slice(-cols*maxRows);for(let i=0;i<visible.length;i++){const x=30+(i%cols)*13,y=42+Math.floor(i/cols)*13;this.dot(x,y,visible[i]?C.pink:C.blue,3)}if(!s.total)this.text('Run a batch to release the first trials.',this.w/2,this.h*.45,C.muted,this.w<450?12:16,'center');const y=this.h-73,w=this.w-70,observed=s.total?s.hits/s.total:0;this.line([[35,y],[35+w,y]],C.grid,8);if(s.total)this.line([[35,y],[35+w*observed,y]],C.pink,8);const expectedX=35+w*this.v.p/100;this.line([[expectedX,y-12],[expectedX,y+12]],C.white,2);this.text(s.total?`${s.hits} / ${s.total} pink · ${(observed*100).toFixed(1)}% observed`:'Expected probability is marked in white.',this.w/2,this.h-38,C.white,this.w<450?11:14,'center');}
 pythagoras(){const{a,b}=this.v,c=hypotenuse(a,b);const raw=[[-a,0],[0,0],[0,b],[-a,-a],[0,-a],[-b,b],[-b,0],[a,0],[a+b,a],[b,a+b],[0,b]];const xmin=-Math.max(a,b),xmax=a+b,ymin=-a,ymax=a+b;const s=Math.min((this.w-100)/(xmax-xmin),(this.h-100)/(ymax-ymin));const ox=(this.w-(xmax-xmin)*s)/2-xmin*s,oy=30+ymax*s,xy=(x,y)=>[ox+x*s,oy-y*s];this.poly([xy(0,0),xy(a,0),xy(a,-a),xy(0,-a)],C.blue,.16);this.poly([xy(0,0),xy(0,b),xy(-b,b),xy(-b,0)],C.amber,.16);this.poly([xy(a,0),xy(0,b),xy(b,a+b),xy(a+b,a)],C.mint,.16);this.poly([xy(0,0),xy(a,0),xy(0,b)],C.white,.025);const q=Math.min(a,b)*.16;this.line([xy(q,0),xy(q,q),xy(0,q)],C.white,1.5);this.text(`a² = ${(a*a).toFixed(1)}`,...xy(a/2,-a/2),C.blue,Math.max(10,Math.min(14,s*.6)),'center');this.text(`b² = ${(b*b).toFixed(1)}`,...xy(-b/2,b/2),C.amber,Math.max(10,Math.min(14,s*.6)),'center');this.text(`c² = ${(c*c).toFixed(1)}`,...xy((a+b)/2,(a+b)/2),C.mint,Math.max(10,Math.min(14,s*.6)),'center');this.text(`${(a*a).toFixed(1)} + ${(b*b).toFixed(1)} = ${(c*c).toFixed(1)}`,this.w/2,this.h-36,C.white,16,'center');}
 volume(){const s=this.v.s;const unit=Math.min(this.w/13,this.h/7);const project=(x,y,z,cx,cy)=>[cx+(x-z)*unit*.85,cy+(x+z)*unit*.35-y*unit];const cube=(scale,cx,cy,color)=>{const p=(x,y,z)=>project(x,y,z,cx,cy);this.poly([p(0,0,0),p(scale,0,0),p(scale,scale,0),p(0,scale,0)],color,.12);this.poly([p(0,0,0),p(0,0,scale),p(0,scale,scale),p(0,scale,0)],color,.23);this.poly([p(0,scale,0),p(scale,scale,0),p(scale,scale,scale),p(0,scale,scale)],color,.32);for(let k=1;k<scale;k++){this.line([p(k,0,0),p(k,scale,0),p(k,scale,scale)],color,.65);this.line([p(0,0,k),p(0,scale,k),p(scale,scale,k)],color,.65);this.line([p(0,k,scale),p(0,k,0),p(scale,k,0)],color,.65)}};cube(1,this.w*.23,this.h*.57,C.blue);cube(s,this.w*.68,this.h*.60,C.mint);this.text('ORIGINAL',this.w*.23,this.h-83,C.blue,11,'center');this.text(`${s.toFixed(1)}× SCALE`,this.w*.68,this.h-83,C.mint,11,'center');this.text(`Area ×${(s*s).toFixed(2)}     Volume ×${(s**3).toFixed(2)}`,this.w/2,this.h-38,C.white,this.w<450?12:16,'center');}
}

Object.assign(Experiment.prototype,extraRenderers);

Object.assign(Experiment.prototype,rareRenderers);
